#include <gtk/gtk.h>
/* reference-overview reference-list reference-form reference-settings */
static void activate(GtkApplication *app,gpointer data){GtkWidget *w=gtk_application_window_new(app),*s=gtk_scrolled_window_new(),*c=gtk_box_new(GTK_ORIENTATION_VERTICAL,14);gtk_window_set_title(GTK_WINDOW(w),"MD3 Reference");gtk_window_set_default_size(GTK_WINDOW(w),820,700);gtk_widget_set_margin_start(c,24);gtk_widget_set_margin_end(c,24);gtk_widget_set_margin_top(c,24);gtk_widget_set_margin_bottom(c,24);gtk_box_append(GTK_BOX(c),gtk_label_new("Classic Material Design 3"));gtk_box_append(GTK_BOX(c),gtk_label_new("Cross-platform reference app"));gtk_box_append(GTK_BOX(c),gtk_button_new_with_label("Primary action"));gtk_box_append(GTK_BOX(c),gtk_label_new("Overview · Token / Adaptive / State"));GtkWidget *list=gtk_list_box_new();gtk_list_box_append(GTK_LIST_BOX(list),gtk_label_new("Item A · Supporting information"));gtk_list_box_append(GTK_LIST_BOX(list),gtk_label_new("Item B · Supporting information"));gtk_box_append(GTK_BOX(c),list);GtkWidget *e=gtk_entry_new();gtk_entry_set_placeholder_text(GTK_ENTRY(e),"Display name");gtk_editable_set_text(GTK_EDITABLE(e),"Material User");gtk_box_append(GTK_BOX(c),e);GtkWidget *r=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,10);gtk_box_append(GTK_BOX(r),gtk_switch_new());gtk_box_append(GTK_BOX(r),gtk_label_new("Enable notifications"));gtk_box_append(GTK_BOX(c),r);gtk_box_append(GTK_BOX(c),gtk_button_new_with_label("Save"));gtk_box_append(GTK_BOX(c),gtk_label_new("Settings · Theme follows the system; content stays readable and operable as the window changes."));gtk_scrolled_window_set_child(GTK_SCROLLED_WINDOW(s),c);gtk_window_set_child(GTK_WINDOW(w),s);gtk_window_present(GTK_WINDOW(w));}
int main(int argc,char **argv){GtkApplication *a=gtk_application_new("org.example.md3reference",G_APPLICATION_DEFAULT_FLAGS);g_signal_connect(a,"activate",G_CALLBACK(activate),NULL);int r=g_application_run(G_APPLICATION(a),argc,argv);g_object_unref(a);return r;}
